#!/bin/sh
# One-command offline reproduction. Compiler invocations in each stage are serial.
set -eu
cd "$(dirname "$0")/../.."
export PYTHONDONTWRITEBYTECODE=1
mkdir -p logs/r7
work="$PWD/logs/r7/build"
# This directory is exclusively generated by the round-seven build.
trap 'rm -rf "$work"' EXIT
sh spike/r7/prepare.sh
sh spike/r7/certify.sh
sh spike/r7/check-lean.sh Hybrid7
sh spike/r7/shake.sh
shasum -a 256 -c spike/r7/pins.sha256
wc -c core/FixedOwner6.wasm core/Kernel7.wasm core/Core7.wasm core/Shake7.wasm
echo 'PASS Round 7'
